  {"q":"'मिठाईवाला' कहानी के लेखक कौन हैं?","o":["जयशंकर प्रसाद","भगवतीप्रसाद वाजपेयी","हरिऔध","प्रेमचंद"],"a":1,"e":"'मिठाईवाला' भगवतीप्रसाद वाजपेयी की कहानी है।","ch":"मिठाईवाला"},
  {"q":"'माता-पिता' में कौन सा समास है?","o":["तत्पुरुष","कर्मधारय","बहुव्रीहि","द्वंद्व"],"a":3,"e":"दोनों पद प्रधान हैं और 'और' से जुड़ते हैं, इसलिए यह द्वंद्व समास है।","ch":"व्याकरण: समास"},
  {"q":"'मुख चंद्र के समान सुंदर है' में कौन सा अलंकार है?","o":["अनुप्रास","यमक","उपमा","श्लेष"],"a":2,"e":"यहाँ मुख की तुलना चंद्रमा से 'समान' शब्द द्वारा की गई है, अतः उपमा अलंकार है।","ch":"व्याकरण: अलंकार"},
  {"q":"'राम ने रावण को मारा' वाक्य में 'को' चिह्न किस कारक का है?","o":["कर्म कारक","कर्ता कारक","करण कारक","संप्रदान कारक"],"a":0,"e":"जिस पर क्रिया का फल पड़ता है वह कर्म है, और 'को' कर्म कारक का चिह्न है।","ch":"व्याकरण: कारक"},
  {"q":"'सूर्य + उदय' का संधि रूप क्या है?","o":["सूर्यउदय","सूर्यादय","सुर्योदय","सूर्योदय"],"a":3,"e":"'अ' और 'उ' मिलकर 'ओ' बनते हैं, यह गुण संधि है, इसलिए सूर्योदय बनता है।","ch":"व्याकरण: संधि"},
  {"q":"'एक तिनका' कविता के कवि कौन हैं?","o":["शिवमंगल सिंह सुमन","अयोध्या सिंह उपाध्याय हरिऔध","सुमित्रानंदन पंत","निराला"],"a":1,"e":"'एक तिनका' अयोध्या सिंह उपाध्याय 'हरिऔध' की कविता है।","ch":"एक तिनका"},
  {"q":"मुहावरे 'नाक में दम करना' का अर्थ क्या है?","o":["खुश करना","नाक सूँघना","बहुत परेशान करना","बीमार होना"],"a":2,"e":"इस मुहावरे का अर्थ है किसी को बहुत तंग करना।","ch":"व्याकरण: मुहावरे"},
  {"q":"'वह खेल रहा है' वाक्य में कौन सा काल है?","o":["भूतकाल","वर्तमान काल","भविष्यत् काल","सामान्य भूतकाल"],"a":1,"e":"क्रिया का चलता हुआ रूप 'रहा है' वर्तमान काल बताता है।","ch":"व्याकरण: काल"},
  {"q":"वीर रस का स्थायी भाव क्या है?","o":["उत्साह","शोक","भय","जुगुप्सा"],"a":0,"e":"वीर रस का स्थायी भाव उत्साह होता है।","ch":"व्याकरण: रस"},
  {"q":"'हम पंछी उन्मुक्त गगन के' कविता के कवि कौन हैं?","o":["हरिऔध","पंत","महादेवी वर्मा","शिवमंगल सिंह सुमन"],"a":3,"e":"यह कविता शिवमंगल सिंह 'सुमन' ने लिखी है।","ch":"हम पंछी उन्मुक्त गगन के"}
